# ---------------------------------------------------------------- poses
def get_poses():
    """(key, description, 7 joint angles). Cached in data/arm_hold/poses.npz (the filter needs the geo_kin license)."""
    cache = OUT / "poses.npz"
    if cache.exists():
        z = np.load(cache)
        return [(k, str(z[k + "_desc"]), z[k]) for k in ("fail1_a_wristB_start", "fail2_b1_wristB_end", "pass_b1_wristB_start")]
    cands = {c["id"]: c for c in build_candidates(ARM)}
    on = {}
    for cid in ("a/wristB", "b1/wristB"):
        c = cands[cid]
        policy = BranchJumpPolicy(ARM, c["end"], start=c["start"], duration=DURATION, profile="smooth")
        on[cid] = run_trajectory(policy, "previous", HOLD)[2]["on"]
    poses = [("fail1_a_wristB_start", "FAIL 1: a/wristB start (lowering to rest)", on["a/wristB"][0]),
             ("fail2_b1_wristB_end", "FAIL 2: b1/wristB end (forward at shoulder height, fully extended)", on["b1/wristB"][-1]),
             ("pass_b1_wristB_start", "PASS: b1/wristB start (forward at shoulder height, elbow bent 90 deg)", on["b1/wristB"][0])]
    OUT.mkdir(parents=True, exist_ok=True)
    np.savez(cache, **{k: q for k, _, q in poses}, **{k + "_desc": d for k, d, _ in poses})
    return poses


# ---------------------------------------------------------------- model / sim
def build(lift=True, dt=DT, spec_hook=None, arm_actuators=True):
    """Gravcomp is always on: add_arm_actuators applies it. arm_actuators=False reproduces the old model
    (torque motors + Python PD, no armature) for experiments/arm_hold_fixes.py, with gravcomp set here."""
    spec = mujoco.MjSpec.from_file(str(SCENE))
    if arm_actuators:
        add_arm_actuators(spec)
    else:
        for n in GRAVCOMP_BODIES:
            spec.body(n).gravcomp = 1.0
    if lift:
        add_pedestal_lift(spec, PS)
    if spec_hook is not None:
        spec_hook(spec)
    m = spec.compile()
    m.opt.timestep = dt
    return m


class HoldSim:
    """Hold-pose simulator. The optional arguments are for the what-if tests in arm_hold_fixes.py only:
    dt (physics and PD step), spec_hook (edit the MjSpec before compiling), kd_scale (scale the wrist
    j5-j7 kd of the Python PD, both arms), native_pd (arm joints driven by MuJoCo position actuators
    instead of the Python PD; the hook must have turned them into position actuators)."""

    def __init__(self, dt=DT, spec_hook=None, kd_scale=1.0, native_pd=False, arm_actuators=True):
        self.dt, self.hz, self.native_pd = dt, 1.0 / dt, native_pd
        self.m = m = build(True, dt, spec_hook, arm_actuators)
        self.d = mujoco.MjData(m)
        self.aid = lambda n: mujoco.mj_name2id(m, mujoco.mjtObj.mjOBJ_ACTUATOR, n)
        self.arm_act = {s: [self.aid(f"{s}_joint{i}_ctrl") for i in range(1, 8)] for s in ("left", "right")}
        self.qadr = lambda a: m.jnt_qposadr[m.actuator_trnid[a, 0]]
        self.dadr = lambda a: m.jnt_dofadr[m.actuator_trnid[a, 0]]
        self.ped = self.aid(PS["actuator_name"])
        self.ctrl = RobotController(m)
        self.wrist_ids = [self.arm_act[s][j] for s in ("left", "right") for j in (4, 5, 6)]
        if isinstance(kd_scale, dict):                  # {0-based joint index: scale}, both arms
            for j, sc in kd_scale.items():
                self.ctrl.kd[[self.arm_act[s_][j] for s_ in ("left", "right")]] *= sc
        else:                                           # one scale for the wrist j5-j7
            self.ctrl.kd[self.wrist_ids] *= kd_scale
        self.arm_ids_all = self.arm_act["left"] + self.arm_act["right"]
        names = [m.actuator(a).name for a in range(m.nu)]
        self.pd_mask = np.array(["_joint" in n or "_finger" in n or n == PS["actuator_name"] for n in names])
        self.lo, self.hi = m.actuator_forcerange[:, 0], m.actuator_forcerange[:, 1]
        self.limited = (self.hi > self.lo) & ~self.ctrl.is_position_actuator
        self.base_dof = m.jnt_dofadr[[j for j in range(m.njnt) if m.jnt_type[j] == 0][0]]
        self.tcp = m.body(f"openarm_{ARM}_hand_tcp").id
        self.arm_body_ids = {m.body(n).id for n in ARM_BODIES}
        self.body_name = [m.body(i).name for i in range(m.nbody)]
        self.d2 = mujoco.MjData(m)

    def reset(self, q_arm, spawn):
        m, d = self.m, self.d
        mujoco.mj_resetData(m, d)
        d.qpos[0:3] = spawn
        for s in ("left", "right"):
            for a, v in zip(self.arm_act[s], q_arm if s == ARM else SOLVER_DEFAULT_Q):
                d.qpos[self.qadr(a)] = v
        mujoco.mj_forward(m, d)
        self.targets = np.zeros(m.nu)
        for s in ("left", "right"):
            self.targets[self.arm_act[s]] = q_arm if s == ARM else SOLVER_DEFAULT_Q
        for a in range(m.nu):
            if "_finger" in m.actuator(a).name:
                self.targets[a] = d.qpos[self.qadr(a)]
        self.targets[self.ped] = PS["target_height"]

    def step(self):
        d = self.d
        raw = self.ctrl.step(self.targets, {"joint_angles": d.qpos, "joint_velocities": d.qvel})
        pd = np.where(self.limited, np.clip(raw, self.lo, self.hi), raw)
        d.ctrl[:] = np.where(self.pd_mask, pd, 0.0)
        if self.native_pd:                                # MuJoCo servo: ctrl is the target angle
            d.ctrl[self.arm_ids_all] = self.targets[self.arm_ids_all]
        d.qvel[self.base_dof:self.base_dof + 2] = 0.0
        d.qvel[self.base_dof + 3:self.base_dof + 6] = 0.0
        mujoco.mj_step(self.m, d)
        return raw, pd

    def hand_sag_mm(self, q_pd):
        """Hand (tcp) distance from where the tracked joints put it, at the same base pose."""
        self.d2.qpos[:] = self.d.qpos
        for a, v in zip(self.arm_act[ARM], q_pd):
            self.d2.qpos[self.qadr(a)] = v
        mujoco.mj_kinematics(self.m, self.d2)
        return 1000.0 * float(np.linalg.norm(self.d.xpos[self.tcp] - self.d2.xpos[self.tcp])), \
            1000.0 * float(self.d.xpos[self.tcp][2] - self.d2.xpos[self.tcp][2])

    def run(self, q_pd, spawn, log_contacts=True, hold_s=HOLD_S, kick=None):
        """0.5 s settle + hold_s hold from exactly q_pd; every physics step logged.
        kick=(joint 1-7, rad/s): add that velocity to the joint once, at the end of the 0.5 s settle."""
        m, d = self.m, self.d
        self.reset(q_pd, spawn)
        n = int(round((SETTLE_S + hold_s) * self.hz))
        k_kick = int(round(SETTLE_S * self.hz))
        acts = self.arm_act[ARM]
        q_ad = [self.qadr(a) for a in acts]
        d_ad = [self.dadr(a) for a in acts]
        L = {k: np.zeros((n, 7)) for k in ("q", "qd", "raw", "clip", "force")}
        L["t"] = np.zeros(n)
        L["sag"] = np.zeros(n)
        contacts = []
        f6 = np.zeros(6)
        for k in range(n):
            if kick is not None and k == k_kick:
                d.qvel[d_ad[kick[0] - 1]] += kick[1]
            raw, pd = self.step()
            L["t"][k] = d.time
            L["q"][k], L["qd"][k] = d.qpos[q_ad], d.qvel[d_ad]
            L["raw"][k], L["clip"][k], L["force"][k] = raw[acts], pd[acts], d.actuator_force[acts]
            L["sag"][k] = self.hand_sag_mm(q_pd)[0]
            if log_contacts:
                for i in range(d.ncon):
                    c = d.contact[i]
                    b1, b2 = m.geom_bodyid[c.geom1], m.geom_bodyid[c.geom2]
                    if b1 in self.arm_body_ids or b2 in self.arm_body_ids:
                        mujoco.mj_contactForce(m, d, i, f6)
                        contacts.append((k, self.body_name[b1], self.body_name[b2], float(f6[0]), float(c.dist)))
        L["limit"] = np.array([max(abs(self.lo[a]), abs(self.hi[a])) for a in acts])
        L["target"] = np.asarray(q_pd, float)
        L["err"] = L["target"] - L["q"]
        L["ped_q_mm"] = 1000.0 * float(d.qpos[m.joint("MiddleBottom").qposadr[0]])
        L["sag_xyz"] = self.hand_sag_mm(q_pd)
        return L, contacts


# ---------------------------------------------------------------- analysis
def classify(err, t, dt=DT):
    """settled / oscillating / drifting for one joint's error over the last 1 s."""
    w = err[t >= t[-1] - 1.0]
    p2p = float(w.max() - w.min())
    if p2p < SETTLED_P2P:
        return "settled", 0.0, p2p / 2
    x = w - w.mean()
    cross = int(np.sum(np.diff(np.sign(x)) != 0))
    spec = np.abs(np.fft.rfft(x))
    spec[0] = 0
    freq = float(np.fft.rfftfreq(len(x), dt)[spec.argmax()])
    return ("oscillating" if cross >= 6 else "drifting"), freq, p2p / 2


def group(body, arm_side):
    if body in ARM_BODIES:
        side = "left" if "_left_" in body else "right"
        return "this-arm" if side == arm_side else "other-arm"
    return "base/torso/pedestal/floor/other"


def contact_summary(contacts, t):
    pairs = {}
    for k, b1, b2, fn, dist in contacts:
        if t[k] < SETTLE_S:
            continue
        key = tuple(sorted((b1, b2)))
        e = pairs.setdefault(key, [0, 0.0, 0.0, 0.0])
        e[0] += 1
        e[1] = max(e[1], fn)
        e[2] += fn
        e[3] = min(e[3], dist)
    return {k: dict(steps=v[0], max_n=v[1], mean_n=v[2] / v[0], min_dist_mm=1000 * v[3]) for k, v in pairs.items()}


def static_checks(sim_gc, q_pd):
    """Gravity load vs compensation per joint, effective inertia, explicit-PD stability margins, limits."""
    out = {}
    d = sim_gc.d
    sim_gc.reset(q_pd, SPAWN_SETTLED)
    d.qvel[:] = 0
    mujoco.mj_forward(sim_gc.m, d)
    acts = sim_gc.arm_act[ARM]
    dofs = [sim_gc.dadr(a) for a in acts]
    tau_g = -d.qfrc_bias[dofs]                      # gravity generalized force on each joint (qvel = 0)
    comp = d.qfrc_gravcomp[dofs]
    out["gravity"], out["comp"], out["resid"] = tau_g, comp, tau_g + comp
    M = np.zeros((sim_gc.m.nv, sim_gc.m.nv))
    mujoco.mj_fullM(sim_gc.m, d, M)
    out["Mjj"] = np.array([M[i, i] for i in dofs])
    out["kp"], out["kd"] = sim_gc.ctrl.kp[acts], sim_gc.ctrl.kd[acts]
    out["kd_dt_over_M"] = out["kd"] * DT / out["Mjj"]            # explicit velocity feedback: unstable above 2
    out["kp_dt2_over_M"] = out["kp"] * DT ** 2 / out["Mjj"]
    jid = [sim_gc.m.actuator_trnid[a, 0] for a in acts]
    out["jlo"], out["jhi"] = sim_gc.m.jnt_range[jid, 0], sim_gc.m.jnt_range[jid, 1]
    out["jlimited"] = sim_gc.m.jnt_limited[jid].astype(bool)
    out["armature"] = sim_gc.m.dof_armature[dofs]
    out["damping"] = sim_gc.m.dof_damping[dofs]
    out["frictionloss"] = sim_gc.m.dof_frictionloss[dofs]
    return out


# ---------------------------------------------------------------- output
def write_csvs(key, L, contacts):
    with open(OUT / f"{key}_log.csv", "w", newline="") as fh:
        w = csv.writer(fh)
        head = ["t"] + [f"j{i}_{c}" for i in range(1, 8) for c in
                        ("target", "pos", "err", "vel", "ctrl_raw", "ctrl_clipped", "force_applied", "limit")]
        w.writerow(head)
        for k in range(len(L["t"])):
            row = [f"{L['t'][k]:.5f}"]
            for j in range(7):
                row += [f"{L['target'][j]:.6f}", f"{L['q'][k, j]:.6f}", f"{L['err'][k, j]:.6f}", f"{L['qd'][k, j]:.6f}",
                        f"{L['raw'][k, j]:.4f}", f"{L['clip'][k, j]:.4f}", f"{L['force'][k, j]:.4f}", f"{L['limit'][j]:.1f}"]
            w.writerow(row)
    with open(OUT / f"{key}_contacts.csv", "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["t", "body1", "body2", "normal_force_N", "dist_mm"])
        for k, b1, b2, fn, dist in contacts:
            w.writerow([f"{L['t'][k]:.5f}", b1, b2, f"{fn:.3f}", f"{1000 * dist:.3f}"])


def plot(key, desc, L, contacts, summ):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    t = L["t"]
    fig, axes = plt.subplots(3, 1, figsize=(12, 11), sharex=True, facecolor=SURFACE,
                             gridspec_kw=dict(height_ratios=[3, 3, 2]))
    ext = {k: v for k, v in summ.items() if not all(b in ARM_BODIES and ("finger" in b) for b in k)}
    # contact steps involving anything that is not a finger-finger overlap, force > 1 N
    marks = np.zeros(len(t), bool)
    for k, b1, b2, fn, dist in contacts:
        if fn > 1.0 and not ("finger" in b1 and "finger" in b2):
            marks[k] = True
    for ax in axes[:2]:
        ax.set_facecolor(SURFACE)
        ax.axvline(SETTLE_S, color=INK2, lw=0.8, ls="--")
        if marks.any():
            ax.fill_between(t, 0, 1, where=marks, transform=ax.get_xaxis_transform(), color="#d6455d", alpha=0.15, lw=0)
    for j in range(7):
        axes[0].plot(t, L["err"][:, j], color=SERIES[j], lw=1.1, label=f"joint {j + 1}")
        axes[1].plot(t, 100 * np.abs(L["force"][:, j]) / L["limit"][j], color=SERIES[j], lw=1.1)
    axes[0].set_ylabel("error = target - actual (rad)", color=INK, fontsize=11)
    axes[1].set_ylabel("applied torque (% of limit)", color=INK, fontsize=11)
    axes[1].axhline(100, color=INK2, lw=0.9, ls=":")
    axes[1].set_ylim(-3, 112)
    ax = axes[2]
    ax.set_facecolor(SURFACE)
    pairs = sorted(summ.items(), key=lambda kv: -kv[1]["max_n"])[:5]
    styles = ["-", "--", "-.", ":", (0, (5, 1))]
    for (pair, st), ls in zip(pairs, styles):
        f = np.zeros(len(t))
        for k, b1, b2, fn, dist in contacts:
            if tuple(sorted((b1, b2))) == pair:
                f[k] += fn
        ax.plot(t, f, color=INK2, lw=1.2, ls=ls,
                label=f"{pair[0].replace('openarm_', '')} ~ {pair[1].replace('openarm_', '')} (max {st['max_n']:.0f} N)")
    if not pairs:
        ax.text(0.5, 0.5, "no contacts involving an arm body", transform=ax.transAxes, ha="center", color=INK2)
    ax.axvline(SETTLE_S, color=INK2, lw=0.8, ls="--")
    ax.set_ylabel("contact normal force (N)\n(arm bodies; top 5 pairs)", color=INK, fontsize=11)
    ax.set_xlabel("time (s)   [dashed line: 0.5 s, after the base has landed; red shading: non-finger contact above 1 N]",
                  color=INK2, fontsize=10)
    for ax in axes:
        ax.grid(color=GRID, lw=0.8)
        ax.tick_params(colors=INK2)
        for side in ("top", "right"):
            ax.spines[side].set_visible(False)
        for side in ("left", "bottom"):
            ax.spines[side].set_color("#b9b8b2")
    axes[0].legend(ncol=7, frameon=False, loc="upper center", bbox_to_anchor=(0.5, 1.12), fontsize=10, labelcolor=INK2)
    axes[2].legend(frameon=False, fontsize=8.5, labelcolor=INK2, loc="upper right")
    fig.suptitle(f"{desc}   |   final hand sag {L['sag'][-1]:.1f} mm", color=INK, fontsize=12, x=0.01, ha="left")
    fig.tight_layout(rect=(0, 0, 1, 0.95))
    fig.savefig(OUT / f"{key}.png", dpi=120, facecolor=SURFACE)
    plt.close(fig)


def report_pose(key, desc, L, contacts, st, summ, tag, w):
    t = L["t"]
    win = t >= SETTLE_S
    print(f"\n{'=' * 118}\n{desc}   [{tag}]\n{'=' * 118}", file=w)
    print(f"hand sag at the end {L['sag'][-1]:.1f} mm (peak after settle {L['sag'][win].max():.1f} mm; vertical {L['sag_xyz'][1]:+.1f} mm); "
          f"pedestal stage at {L['ped_q_mm']:+.2f} mm (command 0)", file=w)
    print(f"{'joint':5s} {'target':>8s} {'final err':>10s} {'behaviour (last 1 s)':>26s} {'peak torque':>11s} {'saturated':>9s} "
          f"{'limit margin':>12s} {'M_jj':>9s} {'kd*dt/M':>8s} {'contacts':>9s}", file=w)
    for j in range(7):
        beh, f, amp = classify(L["err"][:, j], t)
        bs = f"{beh}" + (f" {f:.0f} Hz +-{amp:.3f} rad" if beh == "oscillating" else f" (+-{amp:.4f})" if beh != "settled" else "")
        sat = 100 * float(np.mean(np.abs(L["force"][win][:, j]) >= L["limit"][j] * 0.999))
        marg = min(L["target"][j] - st["jlo"][j], st["jhi"][j] - L["target"][j]) if st["jlimited"][j] else np.inf
        print(f"{'j' + str(j + 1):5s} {L['target'][j]:8.3f} {L['err'][-1, j]:+10.4f} {bs:>26s} "
              f"{100 * np.abs(L['force'][win][:, j]).max() / L['limit'][j]:10.0f}% {sat:8.0f}% "
              f"{marg:12.3f} {st['Mjj'][j]:9.2e} {st['kd_dt_over_M'][j]:8.2f} {'-':>9s}", file=w)
    print("contacts involving an arm body (after settle):", file=w)
    for pair, s in sorted(summ.items(), key=lambda kv: -kv[1]["max_n"]):
        kinds = "/".join(sorted({group(b, ARM) for b in pair if b in ARM_BODIES} | {group(b, ARM) for b in pair if b not in ARM_BODIES}))
        print(f"   {pair[0]} ~ {pair[1]} [{kinds}]: {s['steps']} steps, max {s['max_n']:.1f} N, mean {s['mean_n']:.1f} N, "
              f"deepest {s['min_dist_mm']:.2f} mm", file=w)
    if not summ:
        print("   none", file=w)


def stability_and_kicks(sim, poses, w):
    """EXTRA (not in the brief): is the explicit PD linearly stable per pose, and does a small kick start the chatter?

    The PD torque is computed outside MuJoCo from the previous step's state, so velocity feedback is explicit:
      v[n+1] = (I - dt M^-1 Kd) v[n] - dt M^-1 Kp x[n],   x[n+1] = x[n] + dt v[n+1]
    with M the 7x7 block of the mass matrix for the arm joints at the pose. Spectral radius > 1 = unstable
    (frictionless; the joints here also have 0.1 N m dry friction and 0.4 N m s/rad damping, which are ignored).
    The kick: from the settled base, set one joint's velocity once and watch 1.5 s.
    """
    print(f"\n{'=' * 118}\nEXTRA: LINEAR STABILITY OF THE EXPLICIT PD AND KICK TESTS (base already settled)\n{'=' * 118}", file=w)
    acts = sim.arm_act[ARM]
    dofs = [sim.dadr(a) for a in acts]
    Kp, Kd = np.diag(sim.ctrl.kp[acts]), np.diag(sim.ctrl.kd[acts])
    for key, desc, q in poses:
        sim.reset(q, SPAWN_SETTLED)
        mujoco.mj_forward(sim.m, sim.d)
        M = np.zeros((sim.m.nv, sim.m.nv))
        mujoco.mj_fullM(sim.m, sim.d, M)
        Mb = M[np.ix_(dofs, dofs)]
        Minv = np.linalg.inv(Mb)
        A_v = np.eye(7) - DT * Minv @ Kd
        B_x = -DT * Minv @ Kp
        A = np.block([[np.eye(7) + DT * B_x, DT * A_v], [B_x, A_v]])       # x[n+1], v[n+1] from x[n], v[n]
        ev = np.abs(np.linalg.eigvals(A))
        wrist = np.abs(np.linalg.eigvals(np.block([[np.eye(3) + DT * B_x[4:, 4:], DT * A_v[4:, 4:]], [B_x[4:, 4:], A_v[4:, 4:]]])))
        print(f"\n{desc}\n   spectral radius of the 7-joint explicit PD: {ev.max():.3f} "
              f"({'UNSTABLE' if ev.max() > 1 + 1e-9 else 'stable'}); wrist block j5-j7 only: {wrist.max():.3f}; "
              f"worst eigenvalue is real and negative (Nyquist flip): {bool(np.isclose(np.linalg.eigvals(A)[np.abs(np.linalg.eigvals(A)).argmax()].imag, 0, atol=1e-6))}", file=w)
        for joint in (5, 6, 7):
            for v0 in (0.003, 0.03, 0.3):
                sim.reset(q, SPAWN_SETTLED)
                for _ in range(int(round(0.5 * HZ))):
                    sim.step()
                sim.d.qvel[dofs[joint - 1]] += v0
                n = int(round(1.5 * HZ))
                err, force = np.zeros((n, 7)), np.zeros((n, 7))
                for k in range(n):
                    sim.step()
                    err[k] = q - sim.d.qpos[[sim.qadr(a) for a in acts]]
                    force[k] = sim.d.actuator_force[acts]
                lim = np.array([max(abs(sim.lo[a]), abs(sim.hi[a])) for a in acts])
                sat = 100 * float(np.mean(np.abs(force[-375:]) >= 0.97 * lim))
                tail = err[-375:]
                outcome = "recovers" if (tail.max(axis=0) - tail.min(axis=0)).max() < 1e-3 and np.abs(err[-1]).max() < 0.01 \
                    else "CHATTERS (stays off target)"
                print(f"   kick j{joint} velocity +{v0:g} rad/s: {outcome}; final worst error {np.abs(err[-1]).max():.3f} rad, "
                      f"saturated {sat:.0f}% of the last 0.5 s", file=w)


# ---------------------------------------------------------------- suite over all candidate poses
def judge_run(L):
    """chatter / final hand error / peak force for one run."""
    tail = L["t"] >= L["t"][-1] - 0.5
    p2p = float((L["err"][tail].max(axis=0) - L["err"][tail].min(axis=0)).max())
    worst = float(np.abs(L["err"][-1]).max())
    return dict(chatter=bool(worst > 0.01 or p2p > 1e-3), worst_err=worst, sag=float(L["sag"][-1]),
                peak=100 * float((np.abs(L["force"]) / L["limit"]).max()),
                sat=100 * float(np.mean(np.abs(L["force"][tail]) >= 0.97 * L["limit"])))


def candidate_poses():
    """Start and end pose (filter output) of every candidate in data/branch_jump/realistic_candidates.txt."""
    cache = OUT / "candidate_poses.npz"
    if cache.exists():
        z = np.load(cache)
        return [(k, z[k]) for k in z.files]
    poses = []
    for c in build_candidates(ARM):
        policy = BranchJumpPolicy(ARM, c["end"], start=c["start"], duration=DURATION, profile="smooth")
        on = run_trajectory(policy, "previous", HOLD)[2]["on"]
        poses += [(f"{c['id']} start", on[0]), (f"{c['id']} end", on[-1])]
    OUT.mkdir(parents=True, exist_ok=True)
    np.savez(cache, **dict(poses))
    return poses


def _suite_line(name, r):
    land, k = r["land"], r["kicks"]
    f = lambda rs: f"{sum(x['chatter'] for x in rs)}/7 chatter, {max(x['sag'] for x in rs):7.2f} mm, {max(x['peak'] for x in rs):4.0f}%"
    return (f"{name:22s} | {'CHATTER' if land['chatter'] else 'ok':8s} {land['sag']:7.2f} mm {land['peak']:5.0f}% | "
            f"{f(k['0.3']):46s} | {f(k['1.0']):46s}")


def _suite_totals(rows):
    n = len(rows)
    k3, k10 = (lambda v: [r["kicks"][v] for r in rows])("0.3"), (lambda v: [r["kicks"][v] for r in rows])("1.0")
    return [
        f"Summary over {n} poses: landing chatter {sum(r['land']['chatter'] for r in rows)}/{n}; "
        f"0.3 rad/s kicks chatter in {sum(any(x['chatter'] for x in ks) for ks in k3)}/{n} poses "
        f"({sum(x['chatter'] for ks in k3 for x in ks)}/{7 * n} runs); "
        f"1.0 rad/s kicks chatter in {sum(any(x['chatter'] for x in ks) for ks in k10)}/{n} poses "
        f"({sum(x['chatter'] for ks in k10 for x in ks)}/{7 * n} runs)",
        f"Worst hand error: landing {max(r['land']['sag'] for r in rows):.2f} mm, 0.3 kicks "
        f"{max(x['sag'] for ks in k3 for x in ks):.2f} mm, 1.0 kicks {max(x['sag'] for ks in k10 for x in ks):.2f} mm; "
        f"peak force {max(max(x['peak'] for x in ks) for ks in k10):.0f}% of limit (1.0 kicks)"]


def suite(arm_actuators=True, tag="", first=0, count=None):
    """Poses first .. first+count of the candidate list: base landing, then kicks of 0.3 and 1 rad/s on each
    of the 7 joints (gravcomp is always on).

    Each pose is written to suite_summary<tag>.txt and suite_rows<tag>.jsonl and flushed as soon as it is
    done, so a crash loses only the pose in progress. first = 0 starts the files afresh; a later chunk
    appends. The totals line is printed after every chunk, over all the rows done so far, and written to
    the summary file once the last pose is in."""
    import json
    poses = candidate_poses()
    last = len(poses) if count is None else min(len(poses), first + count)
    sim = HoldSim(arm_actuators=arm_actuators)
    mode = "w" if first == 0 else "a"
    out, rows_f = open(OUT / f"suite_summary{tag}.txt", mode), open(OUT / f"suite_rows{tag}.jsonl", mode)

    def say(*a):
        print(*a, flush=True)
        print(*a, file=out, flush=True)
    if first == 0:
        say(f"{len(poses)} poses ({'new position actuators' if arm_actuators else 'old torque motors + Python PD'}, gravcomp on); "
            f"per pose: base landing, kicks 0.3 and 1.0 rad/s on j1..j7 (settled base). "
            f"chatter = final error > 0.01 rad or > 1e-3 rad peak-to-peak in the last 0.5 s")
        say(f"{'pose':22s} | {'landing: chatter  hand err  peak force':32s} | {'kicks 0.3: chatter  worst hand err  peak force':46s} | "
            f"{'kicks 1.0: chatter  worst hand err  peak force':46s}")
    for name, q in poses[first:last]:
        print(f"... {name}", file=sys.stderr, flush=True)
        r = dict(name=name, land=judge_run(sim.run(q, SPAWN_DROP, log_contacts=False)[0]),
                 kicks={str(v0): [judge_run(sim.run(q, SPAWN_SETTLED, log_contacts=False, hold_s=1.5, kick=(j, v0))[0])
                                  for j in range(1, 8)] for v0 in (0.3, 1.0)})
        rows_f.write(json.dumps(r) + "\n")
        rows_f.flush()
        say(_suite_line(name, r))
    rows_f.close()
    rows = [json.loads(line) for line in open(OUT / f"suite_rows{tag}.jsonl")]
    print(f"\n[{len(rows)}/{len(poses)} poses done]", flush=True)
    for line in _suite_totals(rows):
        print(line, flush=True)
        if len(rows) == len(poses):
            print(line, file=out, flush=True)
    out.close()


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    poses = get_poses()
    log = open(OUT / "summary.txt", "w")

    class Tee:
        def write(self, s):
            sys.stdout.write(s)
            log.write(s)

        def flush(self):
            sys.stdout.flush()
    w = Tee()
    sim = HoldSim()
    print(f"model: {sim.m.nu} actuators (incl. '{PS['actuator_name']}' held at {PS['target_height']} m); gravcomp on "
          f"{len(GRAVCOMP_BODIES)} bodies; dt {1000 * DT:.3f} ms; integrator {mujoco.mjtIntegrator(sim.m.opt.integrator).name}", file=w)
    print(f"PD gains by joint (left arm): kp {sim.ctrl.kp[sim.arm_act[ARM]]}, kd {sim.ctrl.kd[sim.arm_act[ARM]]}; "
          f"torque limit {[float(max(abs(sim.lo[a]), abs(sim.hi[a]))) for a in sim.arm_act[ARM]]} N m", file=w)
    results = {}
    for key, desc, q in poses:
        print(f"\n... {key}: q = {q}", file=sys.stderr, flush=True)
        L, contacts = sim.run(q, SPAWN_DROP)
        st = static_checks(sim, q)
        summ = contact_summary(contacts, L["t"])
        write_csvs(key, L, contacts)
        plot(key, desc, L, contacts, summ)
        report_pose(key, desc, L, contacts, st, summ, "as in the hold check: base lands from 0.22 m", w)
        Lb, cb = sim.run(q, SPAWN_SETTLED)
        sb = contact_summary(cb, Lb["t"])
        print(f"   control (base already settled, no landing jolt): final sag {Lb['sag'][-1]:.1f} mm, worst final joint error "
              f"{np.abs(Lb['err'][-1]).max():.3f} rad (j{int(np.abs(Lb['err'][-1]).argmax()) + 1}), peak torque "
              f"{100 * (np.abs(Lb['force'][Lb['t'] >= SETTLE_S]).max(axis=0) / Lb['limit']).max():.0f}%; "
              f"external-contact pairs: {[p for p in sb if not all('finger' in b for b in p)] or 'none'}", file=w)
        results[key] = (L, st, summ)
        # item 4
        print("   gravity compensation at this pose (N m per joint, qvel = 0):", file=w)
        print(f"      gravity load                  : {st['gravity']}", file=w)
        print(f"      compensation force applied    : {st['comp']}", file=w)
        print(f"      residual (load + compensation): {st['resid']}   max |residual| {np.abs(st['resid']).max():.2e} N m", file=w)
        print(f"      armature {st['armature']}, joint damping {st['damping']}, frictionloss {st['frictionloss']}", file=w)
        print(f"      kp*dt^2/M {st['kp_dt2_over_M']}", file=w)
    # ---------------------------------------------------------- item 5: actuator mapping
    print(f"\n{'=' * 118}\nCHECK 5: ACTUATOR MAPPING (PASS pose, base settled)\n{'=' * 118}", file=w)
    key, desc, q = poses[2]
    ad = sim.ctrl
    for i in range(1, 8):
        a = sim.arm_act[ARM][i - 1]
        jn = sim.m.joint(sim.m.actuator_trnid[a, 0]).name
        ok = ad.qpos_indices[a] == sim.qadr(a) and ad.qvel_indices[a] == sim.dadr(a)
        print(f"   {sim.m.actuator(a).name:22s} -> joint {jn:22s} qpos[{sim.qadr(a)}] dof {sim.dadr(a)} gear {sim.m.actuator_gear[a, 0]:.0f} "
              f"controller index match: {ok}", file=w)
    push = 0.05
    n = int(round(0.4 * HZ))
    print(f"\n   push one target by +{push} rad for 0.4 s; change in position of all 14 arm joints (rad), minus a no-push run:", file=w)
    base = {}
    for p in (None, *range(7)):
        sim.reset(q, SPAWN_SETTLED)
        for _ in range(int(round(0.5 * HZ))):
            sim.step()
        q0 = np.array([sim.d.qpos[sim.qadr(a)] for s in ("left", "right") for a in sim.arm_act[s]])
        if p is not None:
            sim.targets[sim.arm_act[ARM][p]] += push
        peak = 0.0
        for _ in range(n):
            raw, pd = sim.step()
            peak = max(peak, abs(pd[sim.arm_act[ARM][p]]) if p is not None else 0.0)
        q1 = np.array([sim.d.qpos[sim.qadr(a)] for s in ("left", "right") for a in sim.arm_act[s]])
        base[p] = (q1 - q0, peak)
    lab = lambda i: f"left j{i + 1}" if i < 7 else f"right j{i - 6}"
    for p in range(7):
        dq = base[p][0] - base[None][0]
        others = np.delete(np.abs(dq), p)
        print(f"   push j{p + 1}: j{p + 1} moved {dq[p]:+.4f} rad ({'correct sign' if dq[p] > 0 else 'WRONG SIGN'}); "
              f"largest move of any other joint {others.max():.4f} rad ({lab(int(others.argmax()) + (1 if others.argmax() >= p else 0))}); "
              f"PD torque peak {base[p][1]:.2f} N m", file=w)
    stability_and_kicks(sim, poses, w)
    log.close()


if __name__ == "__main__":
    if "--suite" in sys.argv:
        # --first N --count M: run poses N .. N+M-1 (chunks; --first 0 restarts the output files)
        arg = lambda k: int(sys.argv[sys.argv.index(k) + 1]) if k in sys.argv else None
        suite(arm_actuators="--old" not in sys.argv, tag="_old" if "--old" in sys.argv else "",
              first=arg("--first") or 0, count=arg("--count"))
    else:
        main()
